// Intended function: derive ship capability from installed stable modules so progression comes from equipment composition rather than hard-coded hull tiers.
#include "travel/ShipModules.hpp"
#include <algorithm>
namespace elysium{ShipPerformance evaluateShipModules(const std::vector<ShipModuleDefinition>&d,const std::vector<InstalledShipModule>&i,float hull,float fuel){ShipPerformance o;o.mass=hull;float out=0,draw=0,warp=0;for(auto&m:i){if(!m.enabled)continue;auto x=std::find_if(d.begin(),d.end(),[&](auto&a){return a.moduleId==m.moduleId;});if(x==d.end())continue;float c=std::clamp(m.condition,0.f,1.f);o.mass+=x->mass;out+=x->powerOutput*c;draw+=x->powerDraw;o.heat+=x->heat;o.thrust+=x->thrust*c;warp+=x->warpRating*c;o.shield+=x->shield*c;o.cargo+=x->cargo;o.sensor+=x->sensor*c;o.integrity+=x->integrity*c;}o.powerMargin=out-draw;o.powerStarved=o.powerMargin<0;o.overheated=o.heat>std::max(10.f,out*1.5f);float massPenalty=std::max(1.f,o.mass/100.f);o.warpRangeLy=warp*std::max(1.f,fuel)/massPenalty;if(o.powerStarved)o.warpRangeLy*=.25f;return o;}}
